html:
{% set campus = frappe.get_doc("Campus", doc.campus) if doc.campus else None %}
{% set applicant = frappe.get_doc("Applicant", doc.applicant) if doc.applicant else None %}
{% set snapshot = frappe.get_all("Applicant Fee Assignment", filters={"offer_letter": doc.name, "docstatus": ["!=", 2]}, fields=["*"], limit=1) %}
{% set fee_info = snapshot[0] if snapshot else None %}
{% set pay_amt = (fee_info.final_payable_amount if fee_info else doc.payable_amount) or 0 %}
{% set issued_date = doc.issued_on or frappe.utils.today() %}
{% set fee_deadline = doc.payment_deadline %}

<style>
    @page { size: A4; margin: 15mm 18mm; }
    .letter-page { font-family: 'Times New Roman', Georgia, serif; color: #1a1a1a; font-size: 11pt; line-height: 1.5; max-width: 100%; }

    .letterhead { padding-bottom: 10px; border-bottom: 3px solid #800000; margin-bottom: 18px; }
    .letterhead-inner { display: flex; align-items: flex-start; gap: 18px; }
    .letterhead-logo { flex: 0 0 100px; text-align: center; padding: 4px; }
    .letterhead-logo img { max-width: 90px; max-height: 85px; object-fit: contain; }
    .letterhead-body { flex: 1; min-width: 0; }
    .letterhead-title { font-size: 22pt; font-weight: 700; color: #1a1a1a; margin: 0 0 4px 0; line-height: 1.15; text-transform: uppercase; letter-spacing: 0.02em; }
    .letterhead-sub { font-size: 9pt; color: #333; margin: 0; line-height: 1.4; }
    .letterhead-contact { font-size: 8pt; color: #444; margin-top: 6px; padding-top: 6px; border-top: 1px solid #e0e0e0; }

    .letter-body .salutation { margin-bottom: 8px; font-weight: 600; }
    .letter-body .congrats { font-weight: 700; font-size: 12pt; margin-bottom: 6px; }
    .letter-body .body-date { margin-bottom: 16px; font-weight: 600; }
    .letter-body .para { text-align: justify; margin-bottom: 12px; }
    .letter-body .list { margin: 12px 0 12px 0; padding-left: 22px; }
    .letter-body .list li { margin-bottom: 10px; }
    .letter-body .sub-list { list-style-type: lower-alpha; margin: 6px 0 6px 20px; padding-left: 0; }
    .letter-body .sub-list li { margin-bottom: 4px; }
    .letter-body .list-note { font-size: 10pt; margin-top: 6px; margin-bottom: 12px; font-style: italic; color: #333; }

    .letter-sig { margin-top: 36px; }
    .letter-sig .sig-name { font-weight: 700; font-size: 11pt; margin: 0 0 2px 0; }
    .letter-sig .sig-designation { font-size: 11pt; margin: 0; }

    .letter-footer { 
    margin-top: 40px; 
    padding-top: 10px; 
    font-size: 8pt; 
    color: #666; 
    text-align: center; 
    line-height: 1.4; 
    position: relative;
}
    .bold { font-weight: 700; }
    .letter-footer::before {
    content: "********************************************************";
    display: block;
    text-align: center;
    color: #999;
    margin-bottom: 8px;
    letter-spacing: 1px;
}
</style>

<div class="letter-page">
    <!-- Letterhead -->
    <div class="letterhead">
        <div class="letterhead-inner">
            <div class="letterhead-logo">
                {% if campus and campus.logo %}
                    <img src="{{ campus.logo }}" alt="Logo">
                {% else %}
                    <div style="height: 75px; display:flex; align-items:center; justify-content:center; color: #bbb; font-size: 9pt;">LOGO</div>
                {% endif %}
            </div>
            <div class="letterhead-body">
                <h1 class="letterhead-title">{{ campus.campus_name if campus else "National Law School of India University" }}</h1>
                <p class="letterhead-sub">
                    {{ campus.address if campus else "Nagarbhavi" }}{% if campus and campus.city %}, {{ campus.city }}{% endif %}
                    {% if campus and campus.state %}, {{ campus.state }}{% endif %}
                </p>
                <div class="letterhead-contact">
                    {% if campus and (campus.phone_number or campus.email) %}
                        {% if campus.phone_number %}Telephone: {{ campus.phone_number }}{% endif %}
                        {% if campus.email %} | Email: {{ campus.email }}{% endif %}
                    {% else %}
                        Telephone: 080 - 23101000 | Website: www.nls.ac.in | Email: registrar@nls.ac.in
                    {% endif %}
                </div>
            </div>
        </div>
    </div>

    <!-- Body -->
    <div class="letter-body">
        <div class="salutation">Dear {{ applicant.candidate_name if applicant else "Candidate" }},</div>
        <div class="congrats">Congratulations!</div>
        <div class="body-date">Date: {{ frappe.utils.format_date(issued_date, "d MMMM yyyy") }}</div>

        <p class="para">
            We are glad to provisionally offer you admission to the {{ doc.program }} programme at the
            {{ campus.campus_name if campus else "National Law School of India University (NLSIU), Bengaluru" }}. We look forward to welcoming
            you to {{ campus.campus_name if campus else "NLSIU" }}.
        </p>

        <p class="para">
            Please log in to the Admissions Portal (https://nlsatadmissions.nls.ac.in/) to accept the
            provisional offer of admission and complete the next steps online as indicated below:
        </p>

        <ol class="list">
            <li>
                In order to confirm this provisional offer, you must pay INR {{ "{:,.0f}".format(pay_amt) }} as a confirmation
                fee. The full fees applicable to the individual candidate for the academic year {{ doc.academic_year or doc.admission_year or "2025-2026" }} will have to be paid by {{ frappe.utils.format_date(fee_deadline, "d MMMM yyyy") if fee_deadline else "the date specified in the portal" }}. More information about how to accept this
                provisional offer is available in the email sent to you with the provisional offer of
                admission.
            </li>
            <li>
                This offer is contingent upon the verification of particulars furnished in the
                application form. In the next few days, you may receive an email from the {{ campus.campus_name if campus else "NLSIU" }} admissions team if there are queries on the information and documents submitted
                along with your application. Submitting incomplete, invalid, or false
                information/documents shall result in the withdrawal of the provisional offer of
                admission.
            </li>
            <li>
                You are required to be present at the {{ campus.campus_name if campus else "NLSIU" }} campus{% if campus and campus.city %} in {{ campus.city }}{% else %} in Bengaluru{% endif %}, on {{ frappe.utils.format_date(fee_deadline, "d MMMM yyyy") if fee_deadline else "the date specified in the admissions portal" }},
                onwards for registration and onboarding. The orientation programme will
                commence on the date as communicated to you. The schedule for the orientation will be announced later.
            </li>
            <li>
                On the date of registration, the University will conduct an in-person verification of the original
                certificates you have submitted via the admissions portal. Your provisional admission
                will be confirmed only after successful verification of the following original
                documents and full payment of the fees:
                <ul class="sub-list">
                    <li>Class 10 transcript</li>
                    <li>Class 12 transcript</li>
                    <li>Bachelor's degree certificate and transcript*</li>
                    <li>Caste certificate, if applicable</li>
                    <li>EWS certificate, if applicable</li>
                    <li>Disability certificate, if applicable</li>
                    <li>Documents relating to qualifying for Karnataka category, if applicable</li>
                </ul>
                <div class="list-note">
                    * Candidates who are yet to receive the certificate/transcripts of their Bachelor's degree
                    shall submit a declaration to the effect that the certificate/transcripts shall be submitted on
                    or before December 31, {{ (doc.academic_year or doc.admission_year or "2025")[:4] }}. Their admission will remain provisional until the degree
                    certificate and final marks transcript, indicating that the candidate has met the eligibility
                    criteria, is submitted.
                </div>
            </li>
            <li>
                Failure to submit any of the above valid certificates at the time of verification shall
                result in the withdrawal of the provisional offer of admission.
            </li>
            <li>
                You are also required to submit two passport-size colour photographs to the
                Admissions Office at the time of the verification.
            </li>
            <li>
                The University will send you additional documents in early June. Please upload scans
                of the signed copies as per the instructions, which will follow along with the
                documents. On the date of verification of documents, you will be required to carry
                originals of these documents:
                <ul class="sub-list">
                    <li>Email Receipt of Submission of the Online Anti-Ragging Undertaking Required by the UGC</li>
                    <li>Disciplinary Undertaking</li>
                    <li>Off-Campus Housing Application Form</li>
                    <li>Residential Students' Declaration Form</li>
                </ul>
            </li>
            <li>
                All students of the {{ doc.program }} programme shall be provided with off-campus
                accommodation. Further details about accommodation are available in the email sent
                to you with the provisional offer of admission.
            </li>
            <li>
                The University will organise a welcome and orientation programme for all
                candidates. A detailed schedule regarding the same will be provided in the latter half
                of June.
            </li>
        </ol>

        <!-- Signature -->
        <div class="letter-sig">
            <p class="sig-name">Registrar</p>
            <p class="sig-designation">{{ campus.campus_name if campus else "National Law School of India University" }}</p>
        </div>
    </div>

    <!-- Footer -->
    <div class="letter-footer">
        A University for Legal Studies and Research sponsored by the Bar Council of India and established under Karnataka Act 22 of 1986
    </div>
</div>
